""" This function processes most parts of the initialization file.
    """
def _process_line(
    group: Any, flag: Any, value: Any, is_fixed: Any, dict_: Any
) -> object {
    if (flag == 'coeff') {
        flag = 'coeffs';
    }
    if (('coeffs' not in dict_[group].keys()) and (flag in ['coeffs'])) {
        dict_[group]['coeffs'] = [];
        dict_[group]['fixed'] = [];
    }
    if (flag in ['coeffs']) {
        dict_[group]['coeffs'] += [value];
        dict_[group]['fixed'] += [is_fixed];
    } else {
        dict_[group][flag] = value;
    }
    return dict_;
}

test_blocks:
test "t0" {
    assert (
        _process_line('test_group', 'coeffs', 'test_value', False, {'test_group': {}})
        == {'test_group': {'coeffs': ['test_value'], 'fixed': [False]}}
    );;
}

test "t1" {
    assert (
        _process_line(
            'group', 'coeff', 'value', False, {'group': {'coeffs': [], 'fixed': []}}
        )
        == {'group': {'coeffs': ['value'], 'fixed': [False]}}
    );;
}

test "t2" {
    assert (
        _process_line('group', 'flag', 'value', False, {'group': {'flag': 'wrong'}})
        == {'group': {'flag': 'value'}}
    );;
}

test "t3" {
    assert (
        _process_line('group', 'coeffs', 'value', True, {'group': {'flag': 'wrong'}})
        == {'group': {'coeffs': ['value'], 'flag': 'wrong', 'fixed': [True]}}
    );;
}

test "t4" {
    assert (
        _process_line('group', 'coeffs', 'value', 'is_fixed', {'group': {}})
        == {'group': {'coeffs': ['value'], 'fixed': ['is_fixed']}}
    );;
}

test "t5" {
    assert (
        _process_line(
            'test_group',
            'coeffs',
            'test_value',
            True,
            {'test_group': {'coeffs': [], 'fixed': []}}
        )
        == {'test_group': {'coeffs': ['test_value'], 'fixed': [True]}}
    );;
}

test "t6" {
    assert (
        _process_line('test_group', 'coeffs', 'test_value', True, {'test_group': {}})
        == {'test_group': {'coeffs': ['test_value'], 'fixed': [True]}}
    );;
}

test "t7" {
    assert (
        _process_line(
            'group',
            'coeff',
            'value',
            False,
            {'group': {'coeffs': ['value'], 'fixed': [False]}}
        )
        == {'group': {'coeffs': ['value', 'value'], 'fixed': [False, False]}}
    );;
}

test "t8" {
    assert (
        _process_line(
            'group',
            'coeff',
            'value',
            False,
            {'group': {'coeffs': ['val0'], 'fixed': [True]}}
        )
        == {'group': {'coeffs': ['val0', 'value'], 'fixed': [True, False]}}
    );;
}
